transfer_dtype <- function(x, y){
  switch(
    class(y)[1],
    "factor"=factor(x, levels=levels(y)),
    "integer"=as.integer(x),
    "numeric"=as.numeric(x),
    "character"=as.character(x),
    stop(paste0(class(y)[1]," not supported for dtype transfer!"))
  )
}

suppress_pois_check_warnings <- function(expr) {
  # unwanted warnings with negative lambda may escape ClusterDE's createNull()
  # they are generated by fitdistrplus, for a plausibility check. See:
  # https://forum.posit.co/t/warnings-when-run-inside-mutate-not-when-run-separately/163240
  # fitdistrplus tries to silence them, but sometimes they escape. This adds
  # another layer of silencing, but it also does not always word :-/
  withCallingHandlers(
    expr,
    warning=function(w) {
      warning_call <- if(is.null(conditionCall(w))) "" else paste(deparse(conditionCall(w)), collapse="")
      is_pois_warn <-(
        identical(conditionMessage(w), "NaNs produced") 
        && grepl("^(dpois|ppois)\\(0:1,\\s*lambda\\s*=\\s*-[0-9]", warning_call, perl=TRUE)
      )
      if(is_pois_warn) invokeRestart("muffleWarning")
    }
  )
}